class RecaseError extends Error {
  code;
  statusCode;
  data;
  details;
  constructor({
    message,
    code,
    statusCode = 400,
    data,
    cause,
    details
  }) {
    super(message, cause === undefined ? undefined : { cause });
    this.name = "RecaseError";
    this.code = code || "invalid_request";
    this.statusCode = statusCode;
    this.data = data;
    this.details = details;
  }
}

