function createFilterConfig({
  schema,
  omitFields
}) {
  const shape = schema.shape;
  let objectField = shape.object;
  if (objectField instanceof ZodOptional) {
    objectField = objectField.unwrap();
  }
  const objectType = objectField.value;
  return {
    objectType,
    omitFields
  };
}
