// ../../shared/api/common/responseFilter/stripInternalFields.ts
function stripInternalFields({ data }) {
  if (data === null || typeof data !== "object")
    return data;
  if (Array.isArray(data)) {
    return data.map((item) => stripInternalFields({ data: item }));
  }
  const obj = data;
  const objectType = obj.object;
  const fieldsToOmit = typeof objectType === "string" ? responseFilterConfig[objectType] ?? [] : [];
  const result = {};
  for (const [key, value] of Object.entries(obj)) {
    if (fieldsToOmit.includes(key))
      continue;
    result[key] = stripInternalFields({ data: value });
  }
  return result;
}
