// ../../shared/api/customers/changes/V0.2_CustomerChange.ts
var V0_2_CustomerChange = defineVersionChange({
  name: "V0_2_CustomerChange",
  newVersion: "1.1.0" /* V1_1 */,
  oldVersion: "0.2.0" /* V0_2 */,
  description: [
    "Customer response split into separate objects (customer, products, add_ons, entitlements, invoices)",
    "Features renamed to entitlements",
    "Features: V2 format (usage, included_usage, interval_count) \u2192 V1 format (used, allowance)"
  ],
  affectedResources: ["customer" /* Customer */],
  newSchema: ApiCustomerV2Schema,
  oldSchema: ApiCustomerV1Schema,
  legacyDataSchema: CustomerLegacyDataSchema,
  transformResponse: ({
    input,
    legacyData
  }) => {
    const v1_features = transformFeaturesV2ToV1({
      features: input.features
    });
    const {
      features: _features,
      products = [],
      invoices,
      trials_used,
      ...customerFields
    } = input;
    const mainProducts = products.filter((p) => !p.is_add_on).map((p) => transformCusProductV2ToV1({
      input: p,
      legacyData: legacyData?.cusProductLegacyData[p.id]
    }));
    const addOns = products.filter((p) => p.is_add_on).map((p) => transformCusProductV2ToV1({
      input: p,
      legacyData: legacyData?.cusProductLegacyData[p.id]
    }));
    const processor = customerFields.stripe_id ? {
      type: "stripe",
      id: customerFields.stripe_id
    } : undefined;
    return {
      customer: {
        ...customerFields,
        internal_id: "",
        processor
      },
      products: mainProducts,
      add_ons: addOns,
      entitlements: v1_features,
      invoices: invoices || [],
      trials_used,
      payment_method: customerFields.payment_method
    };
  }
});
function transformFeaturesV2ToV1({
  features
}) {
  const v1_features = [];
  for (const feature of features) {
    if (feature.unlimited) {
      const v1Feature = ApiCusFeatureV1Schema.parse({
        feature_id: feature.feature_id,
        unlimited: true,
        interval: null,
        balance: null,
        used: null
      });
      v1_features.push(v1Feature);
      continue;
    }
    if (!feature.interval && !feature.balance && feature.usage === undefined && feature.included_usage === undefined) {
      const v1Feature = ApiCusFeatureV1Schema.parse({
        feature_id: feature.feature_id,
        interval: null
      });
      v1_features.push(v1Feature);
      continue;
    }
    const v1Feature = ApiCusFeatureV1Schema.parse({
      feature_id: feature.feature_id,
      unlimited: feature.unlimited || false,
      interval: feature.interval,
      balance: feature.balance,
      used: feature.usage,
      next_reset_at: feature.next_reset_at,
      allowance: feature.included_usage,
      usage_limit: feature.usage_limit
    });
    v1_features.push(v1Feature);
  }
  return v1_features;
}

