// ../../shared/utils/productV2Utils/productV2ToProperties.ts
var productV2ToProperties = ({
  productV2,
  trialAvailable
}) => {
  const items = productV2.items;
  const isFree = items.every(isFeatureItem);
  const pricedItems = items.filter((i) => isPriceItem(i) || isFeaturePriceItem(i));
  const isOneOff = !isFree && pricedItems.length > 0 && pricedItems.every((i) => itemToBillingInterval({ item: i }) === "one_off" /* OneOff */);
  const basePriceItem = productV2ToBasePrice({
    product: productV2
  });
  let intervalGroup;
  if (basePriceItem) {
    const billingInterval = itemToBillingInterval({ item: basePriceItem });
    if (billingInterval !== "one_off" /* OneOff */) {
      intervalGroup = billingInterval;
    }
  }
  const updateable = !isOneOff && items.some((i) => isFeaturePriceItem(i) && i.usage_model === "prepaid" /* Prepaid */);
  const hasTrial = notNullish(productV2.free_trial) && trialAvailable;
  return {
    is_free: isFree,
    is_one_off: isOneOff,
    interval_group: intervalGroup,
    updateable,
    has_trial: hasTrial
  };
};

