// ../../shared/api/balances/check/changes/V0.2_CheckChange.ts
var V0_2_CheckChange = defineVersionChange({
  name: "V0.2 Check Change",
  newVersion: "1.1.0" /* V1_1 */,
  oldVersion: "0.2.0" /* V0_2 */,
  description: [
    "Check response transformed to balances array format",
    "Single check result object \u2192 { allowed, balances: [...] }"
  ],
  affectedResources: ["check" /* Check */],
  newSchema: CheckResponseV1Schema,
  oldSchema: CheckResponseV0Schema,
  legacyDataSchema: CheckLegacyDataSchema,
  affectsResponse: true,
  transformResponse: ({
    input,
    legacyData
  }) => {
    const {
      allowed,
      feature_id,
      required_balance,
      balance,
      unlimited,
      overage_allowed
    } = input;
    if (!legacyData) {
      throw new Error("Legacy data is required");
    }
    const { noCusEnts, featureToUse } = legacyData;
    if (noCusEnts && !allowed) {
      return {
        allowed: false,
        balances: []
      };
    }
    const balanceObj = {
      feature_id
    };
    if (featureToUse.type === "boolean" /* Boolean */) {
      return {
        allowed,
        balances: [
          {
            feature_id,
            balance: null
          }
        ]
      };
    }
    if (balance === null && !unlimited && !overage_allowed && required_balance === undefined) {
      balanceObj.balance = null;
      return {
        allowed,
        balances: [balanceObj]
      };
    }
    if (unlimited) {
      balanceObj.balance = null;
      balanceObj.unlimited = true;
      balanceObj.usage_allowed = overage_allowed || false;
      balanceObj.required = null;
      return {
        allowed,
        balances: [balanceObj]
      };
    }
    if (overage_allowed) {
      balanceObj.balance = balance;
      balanceObj.unlimited = false;
      balanceObj.usage_allowed = true;
      balanceObj.required = null;
      return {
        allowed,
        balances: [balanceObj]
      };
    }
    balanceObj.required = required_balance ?? null;
    balanceObj.balance = balance;
    return {
      allowed,
      balances: [balanceObj]
    };
  }
});

