var strictEqual = () => ({ left, right }) => left === right;
var stabilizeBillingControlColumn = (value) => {
  if (value == null)
    return;
  if (!Array.isArray(value))
    return value;
  const stabilize = (entry) => {
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) {
      return entry;
    }
    return Object.keys(entry).sort().reduce((acc, objectKey) => {
      acc[objectKey] = stabilize(entry[objectKey]);
      return acc;
    }, {});
  };
  return value.map(stabilize);
};
