// ../../shared/api/customers/cusFeatures/utils/apiBalanceUtils.ts
var getUnlimitedApiBalance = ({
  apiFeature,
  cusEnts,
  entityId
}) => {
  const feature = cusEnts[0].entitlement.feature;
  const planId = cusEntsToPlanId({ cusEnts });
  const id = cusEnts[0].id;
  const usage = cusEntsToUnlimitedUsage({ cusEnts, entityId });
  const unlimitedCusEnts = cusEnts.filter(isUnlimitedCusEnt);
  return {
    object: "balance",
    feature: apiFeature,
    feature_id: feature.id,
    unlimited: true,
    granted: 0,
    remaining: 0,
    usage,
    next_reset_at: cusEntsToNextResetAt({ cusEnts: unlimitedCusEnts }),
    max_purchase: null,
    overage_allowed: false,
    breakdown: [
      {
        object: "balance_breakdown",
        id,
        plan_id: planId,
        included_grant: 0,
        prepaid_grant: 0,
        remaining: 0,
        usage,
        unlimited: true,
        reset: cusEntsToReset({ cusEnts: unlimitedCusEnts }),
        expires_at: null,
        price: null,
        overage: 0
      }
    ],
    rollovers: cusEntsToRollovers({ cusEnts, entityId })
  };
};
// ../../shared/api/customers/cusFeatures/utils/apiBalanceV2Utils.ts
var mergeAggregatedBalanceIntoApiBalanceV2 = ({
  apiBalance,
  aggregatedFeatureBalance
}) => {
  if (!aggregatedFeatureBalance)
    return apiBalance;
  if (apiBalance.unlimited || aggregatedFeatureBalance.unlimited) {
    const aggregatedUnlimitedUsage = aggregatedFeatureBalance.unlimited ? Object.values(aggregatedFeatureBalance.entities ?? {}).reduce((total, entityBalance) => total.add(entityBalance.balance ?? 0), new Decimal(aggregatedFeatureBalance.balance ?? 0)).neg() : new Decimal(0);
    const usage = aggregatedUnlimitedUsage.add(apiBalance.usage).toNumber();
    return {
      ...apiBalance,
      granted: 0,
      remaining: 0,
      usage,
      unlimited: true,
      overage_allowed: false,
      breakdown: apiBalance.breakdown ?? []
    };
  }
  const aggregatedAllowance = aggregatedFeatureBalance.allowance_total ?? 0;
  const aggregatedPrepaidGrantFromOptions = aggregatedFeatureBalance.prepaid_grant_from_options ?? 0;
  const aggregatedAdjustment = aggregatedFeatureBalance.adjustment ?? 0;
  const aggregatedBalance = aggregatedFeatureBalance.balance ?? 0;
  const aggregatedRolloverBalance = aggregatedFeatureBalance.rollover_balance ?? 0;
  const aggregatedRolloverUsage = aggregatedFeatureBalance.rollover_usage ?? 0;
  const aggregatedRolloverGrant = new Decimal(aggregatedRolloverBalance).add(aggregatedRolloverUsage).toNumber();
  const aggregatedNextResetAt = aggregatedFeatureBalance.next_reset_at ?? null;
  const nextResetAt = apiBalance.next_reset_at === null ? aggregatedNextResetAt : aggregatedNextResetAt === null ? apiBalance.next_reset_at : Math.min(apiBalance.next_reset_at, aggregatedNextResetAt);
  const baseGranted = new Decimal(aggregatedAllowance).add(aggregatedPrepaidGrantFromOptions).add(aggregatedAdjustment).toNumber();
  const granted = new Decimal(baseGranted).add(aggregatedRolloverGrant).toNumber();
  const mainRemaining = Decimal.max(0, new Decimal(aggregatedBalance)).toNumber();
  const remaining = new Decimal(mainRemaining).add(aggregatedRolloverBalance).toNumber();
  const usage = new Decimal(baseGranted).sub(aggregatedBalance).add(aggregatedRolloverUsage);
  return {
    ...apiBalance,
    granted: new Decimal(apiBalance.granted).add(granted).toNumber(),
    remaining: new Decimal(apiBalance.remaining).add(remaining).toNumber(),
    usage: new Decimal(apiBalance.usage).add(usage).toNumber(),
    unlimited: apiBalance.unlimited || aggregatedFeatureBalance.unlimited,
    overage_allowed: apiBalance.overage_allowed || aggregatedFeatureBalance.usage_allowed || false,
    next_reset_at: nextResetAt,
    breakdown: apiBalance.breakdown ?? []
  };
};
var getEmptyApiBalanceV2 = ({
  featureId,
  feature
}) => {
  return {
    object: "balance",
    feature_id: featureId,
    feature,
    granted: 0,
    remaining: 0,
    usage: 0,
    unlimited: false,
    overage_allowed: false,
    max_purchase: null,
    next_reset_at: null,
    breakdown: [],
    rollovers: undefined
  };
};
