class AutumnClientError extends Error {
  status;
  code;
  constructor({
    path,
    status,
    code
  }) {
    super(`Autumn answered ${path} with ${status} (${code ?? "no code"})`);
    this.name = "AutumnClientError";
    this.status = status;
    this.code = code;
  }
}

