// tests/bench/workerAutumn.ts
var WORKER_AUTUMN_PATH = import.meta.dir + "/workerAutumn.js";
if (false)
  ;

// tests/bench/hotCustomerBench.ts
var rate = Number(process.argv[2] ?? 100);
var seconds = Number(process.argv[3] ?? 20);
var pushLagMs = Number(process.argv[4] ?? 1500);
var BALANCES = 40;
var AUTUMN_PORT = 18778;
var PUSH_PORT = 18779;
var WARMUP_MS = pushLagMs + 2000;
var CLOCK_TICK_MS = 10;
var jsThreadCpuMs = () => {
  const fields = readFileSync(`/proc/self/task/${process.pid}/stat`, "utf8").split(") ")[1]?.split(" ");
  return (Number(fields?.[11]) + Number(fields?.[12])) * CLOCK_TICK_MS;
};
var folder = mkdtempSync(join(tmpdir(), "atom-hot-"));
var state = createState({
  customerEntitlements: Array.from({ length: BALANCES }, (_, i) => createCustomerEntitlement({
    id: i === 0 ? "messages_monthly" : `feature_${i}_monthly`,
    featureId: i === 0 ? "messages" : `feature_${i}`,
    balance: 1e8
  }))
});
var subject = { state, catalog: createCatalogFor({ state }), org: atomOrg };
var subjectPath = join(folder, "subject.json");
await Bun.write(subjectPath, JSON.stringify(subject));
var autumn = Bun.spawn([
  process.execPath,
  WORKER_AUTUMN_PATH,
  String(AUTUMN_PORT),
  `http://127.0.0.1:${PUSH_PORT}/`,
  String(pushLagMs),
  subjectPath
], { stdout: "ignore", stderr: "inherit" });
await Bun.sleep(500);
var sqliteStore = openSqliteStore({
  databasePath: join(folder, "slot.sqlite"),
  held: createHeldSubjects({ budgetBytes: 512 * 1024 ** 2 })
});
var journal = openJournal({ databasePath: join(folder, "journal.sqlite") });
var appendUs = 0;
var measuring = false;
var append = journal.append;
journal.append = (params) => {
  const startedAt = performance.now();
  const appended = append(params);
  if (measuring)
    appendUs += (performance.now() - startedAt) * 1000;
  return appended;
};
var processor = createSlotProcessor({
  ctx: {
    sqliteStore,
    catalogStore: openCatalogStore({ databasePath: ":memory:" }),
    logger: getAtomLogger(),
    subjectPulls: noFolderPulls,
    journal
  }
});
var client = createAutumnClient({
  autumnApiUrl: `http://127.0.0.1:${AUTUMN_PORT}`
});
var forwarding = createJournalForwarder({
  ctx: { autumnClient: client, logger: { info() {}, warn() {} } }
}).forward({ journal, tokenHash: () => "hash_bench", pulls: noFolderPulls });
var pushes = 0;
var pushServer = Bun.serve({
  hostname: "127.0.0.1",
  port: PUSH_PORT,
  fetch: async (request) => {
    pushes++;
    await processor.setSubject({
      customerId: request.headers.get(ATOM_CUSTOMER_ID_HEADER) ?? "",
      body: await request.text()
    });
    return new Response(null, { status: 204 });
  }
});
await processor.setSubject({
  customerId: "cus_1",
  body: JSON.stringify({
    ...subject,
    log_offset: "1",
    read_at: 1000
  })
});
var latenciesMs = [];
var pending = [];
var total = rate * seconds;
var startedAt = performance.now();
var cpuBefore = null;
var measuredFrom = 0;
var measuredCalls = 0;
for (let sent = 0;sent < total; ) {
  const now = performance.now();
  if (cpuBefore === null && now - startedAt >= WARMUP_MS) {
    cpuBefore = jsThreadCpuMs();
    measuredFrom = sent;
    measuring = true;
  }
  const due = Math.min(total, Math.floor((now - startedAt) / 1000 * rate));
  for (;sent < due; sent++) {
    const intendedAt = startedAt + (sent + 1) / rate * 1000;
    const measured = cpuBefore !== null;
    pending.push(processor.check({
      request: {
        ...checkRequestFor({
          params: {
            customer_id: "cus_1",
            send_event: true,
            required_balance: 1
          }
        }),
        requestId: `atom_req_${sent}`
      }
    }).then(() => {
      if (measured)
        latenciesMs.push(performance.now() - intendedAt);
    }));
  }
  await Bun.sleep(1);
}
await Promise.all(pending);
measuredCalls = total - measuredFrom;
var cpuMs = jsThreadCpuMs() - (cpuBefore ?? 0);
latenciesMs.sort((a, b) => a - b);
var percentile = (share) => Number((latenciesMs[Math.min(latenciesMs.length - 1, Math.floor(latenciesMs.length * share))] ?? 0).toFixed(2));
console.log(JSON.stringify({
  rate,
  seconds,
  pushLagMs,
  measuredCalls,
  threadCpuMsPerDeduction: Number((cpuMs / measuredCalls).toFixed(3)),
  p50Ms: percentile(0.5),
  p99Ms: percentile(0.99),
  maxMs: percentile(1),
  pushes,
  appendUsPerDeduction: Number((appendUs / measuredCalls).toFixed(2)),
  ...readViewFoldThreadStats(),
  owedAtEnd: journal.owed({ customerId: "cus_1" }).length
}));
forwarding.stop();
pushServer.stop(true);
autumn.kill();
rmSync(folder, { recursive: true, force: true });
process.exit(0);
